    margin: 0 auto;
    padding: 0 1.5rem;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: var(--white);
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Typography */
h1 { font-size: 3.5rem; line-height: 1.1; margin-bottom: 1.5rem; }
h2 { font-size: 2.25rem; margin-bottom: 1rem; }
h3 { font-size: 1.25rem; margin-bottom: 0.5rem; }

@media (max-width: 768px) {
    h1 { font-size: 2.5rem; }
    h2 { font-size: 1.75rem; }
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 24px;
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    text-align: center;
    transition: all 0.3s ease;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-primary:hover {
    background-color: #333;
}

.btn-secondary {
    background-color: var(--secondary-color);
    color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

.btn-outline {
    background-color: transparent;
    border: 2px solid var(--primary-color);
    color: var(--primary-color);
}

.btn-outline:hover {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-sm { padding: 8px 16px; font-size: 0.875rem; }

.btn-link {
    color: var(--primary-color);
    border-bottom: 2px solid var(--accent-color);
    padding-bottom: 2px;
}

.btn-link:hover {
    color: var(--accent-color);
}

/* Header */
.site-header {
    background: var(--white);
    border-bottom: 1px solid #eee;
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.brand .logo-text {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.primary-nav .nav-list {
    display: flex;
    gap: 2rem;
}

.primary-nav a {
    font-weight: 500;
    text-transform: uppercase;
    font-size: 0.875rem;
    letter-spacing: 1px;
}

.primary-nav a[aria-current="page"] {
    color: var(--accent-color);
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    padding: 10px;
}

.header-actions {
    display: flex;
    gap: 1rem;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--primary-color);
    padding: 5px;
}

/* Hero */
.hero {
    padding: 4rem 0;
    background-color: var(--secondary-color);
    overflow: hidden;
}

.hero-container {
    display: flex;
    align-items: center;
    gap: 4rem;
}

.hero-content {
    flex: 1;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-light);
    margin-bottom: 2rem;
}

.hero-image {
    flex: 1;
}

.hero-image img {
    border-radius: 8px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

@media (max-width: 768px) {
    .hero-container {
        flex-direction: column;
        text-align: center;
        gap: 2rem;
    }
}

/* Featured Products */
.featured-products {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--accent-color);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    display: flex;
    flex-direction: column;
}

.product-image {
    background: var(--secondary-color);
    aspect-ratio: 1/1;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1rem;
    border-radius: 4px;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 a:hover {
    color: var(--accent-color);
}

.product-info .price {
    font-weight: 700;
    margin-bottom: 1rem;
}

/* Deals */
.deals {
    padding: 4rem 0;
}

.deals-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 2rem;
}

.deal-card {
    padding: 4rem;
    border-radius: 8px;
    display: flex;
    align-items: center;
}

.deal-main {
    background-color: var(--accent-color);
    color: var(--white);
}

.deal-secondary {
    background-color: var(--primary-color);
    color: var(--white);
}

.deal-content h3 { font-size: 2rem; margin-bottom: 1rem; }
.deal-content p { font-size: 1.1rem; margin-bottom: 2rem; }

@media (max-width: 768px) {
    .deals-grid { grid-template-columns: 1fr; }
    .deal-card { padding: 2rem; }
}

/* Editorial */
.editorial {
    padding: 6rem 0;
}

.editorial-layout {
    display: flex;
    align-items: center;
    gap: 4rem;
}

.editorial-image, .editorial-text { flex: 1; }

.editorial-text h2 { margin-bottom: 1.5rem; }
.editorial-text p { margin-bottom: 1.5rem; color: var(--text-light); }

@media (max-width: 768px) {
    .editorial-layout { flex-direction: column; gap: 2rem; }
}

/* Footer */
.site-footer {
    background: var(--secondary-color);
    padding: 5rem 0 2rem;
    margin-top: 4rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-nav h3, .footer-social h3 {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 1.5rem;
}

.footer-nav li { margin-bottom: 0.75rem; }
.footer-nav a { color: var(--text-light); font-size: 0.9375rem; }
.footer-nav a:hover { color: var(--primary-color); }

.social-links { display: flex; gap: 1rem; }
.social-links a { font-size: 0.875rem; font-weight: 600; }

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid #ddd;
    text-align: center;
    color: var(--text-light);
    font-size: 0.875rem;
}

@media (max-width: 768px) {
    .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
    .footer-brand { grid-column: span 2; }
}

/* Accessibility & Focus */
:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
}

.sr-only:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Mobile Nav Styles */
@media (max-width: 768px) {
    .menu-toggle {
        display: block;
    }

    .nav-list {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background: var(--white);
        flex-direction: column;
        padding: 2rem;
        gap: 1.5rem;
        box-shadow: 0 10px 20px rgba(0,0,0,0.05);
    }

    .nav-list.is-open {
        display: flex;
    }

    .menu-icon {
        width: 24px;
        height: 2px;
        background: var(--primary-color);
        display: block;
        position: relative;
    }

    .menu-icon::before, .menu-icon::after {
        content: '';
        width: 24px;
        height: 2px;
        background: var(--primary-color);
        position: absolute;
        left: 0;
        transition: transform 0.3s;
    }

    .menu-icon::before { top: -8px; }
    .menu-icon::after { bottom: -8px; }

    [aria-expanded="true"] .menu-icon { background: transparent; }
    [aria-expanded="true"] .menu-icon::before { transform: translateY(8px) rotate(45deg); }
    [aria-expanded="true"] .menu-icon::after { transform: translateY(-8px) rotate(-45deg); }
}
