* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--white);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: inherit;
    text-decoration: none;
    transition: color 0.3s ease;
}

ul {
    list-style: none;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: var(--white);
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Typography */
h1 { font-size: 3.5rem; line-height: 1.1; margin-bottom: 1.5rem; }
h2 { font-size: 2.25rem; margin-bottom: 1rem; }
h3 { font-size: 1.25rem; margin-bottom: 0.5rem; }

@media (max-width: 768px) {
    h1 { font-size: 2.5rem; }
    h2 { font-size: 1.75rem; }
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 24px;
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    text-align: center;
    transition: all 0.3s ease;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-primary:hover {
    background-color: #333;
}

.btn-secondary {
    background-color: var(--secondary-color);
    color: var(--primary-color);
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

.btn-outline {
    background-color: transparent;
    border: 2px solid var(--primary-color);
    color: var(--primary-color);
}

.btn-outline:hover {
    background-color: var(--primary-color);
    color: var(--white);
}

.btn-sm { padding: 8px 16px; font-size: 0.875rem; }

.btn-link {
    color: var(--primary-color);
    border-bottom: 2px solid var(--accent-color);
    padding-bottom: 2px;
}

.btn-link:hover {
    color: var(--accent-color);
}

/* Header */
.site-header {
    background: var(--white);
    border-bottom: 1px solid #eee;
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.brand .logo-text {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.primary-nav .nav-list {
    display: flex;
    gap: 2rem;
}

.primary-nav a {
    font-weight: 500;
    text-transform: uppercase;
    font-size: 0.875rem;
    letter-spacing: 1px;
}

.primary-nav a[aria-current="page"] {
    color: var(--primary-color);
    border-bottom: 2px solid var(--accent-color);
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    padding: 10px;
}

.header-actions {
    display: flex;
    gap: 1rem;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--primary-color);
    padding: 5px;
}

/* Hero */
.hero {
    padding: 4rem 0;
    background-color: var(--secondary-color);
    overflow: hidden;
}

.hero-container {
    display: flex;
    align-items: center;
    gap: 4rem;
}

.hero-content {
    flex: 1;
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--text-light);
    margin-bottom: 2rem;
}

.hero-image {
    flex: 1;
}

.hero-image img {
    border-radius: 8px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

@media (max-width: 768px) {
    .hero-container {
        flex-direction: column;
        text-align: center;
        gap: 2rem;
    }
}

/* Featured Products */
.featured-products {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--accent-color);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    display: flex;
    flex-direction: column;
}

.product-image {
    background: var(--secondary-color);
    aspect-ratio: 1/1;
    display: flex;
